// The MCP App page for eokg_view_image. src/apps/image-viewer.html is generated by `npm run build:viewer`.

import { readFileSync } from 'node:fs';
import { registerAppResource, RESOURCE_MIME_TYPE } from '@modelcontextprotocol/ext-apps/server';
import { VIEWER_RESOURCE_URI } from '../tools/view_image.js';

const html = readFileSync(new URL('./image-viewer.html', import.meta.url), 'utf8');

// The image host only; the page bundles all its code and fetches nothing.
const UI_META = { csp: { resourceDomains: ['https://data.odeuropa.eu'], connectDomains: [] }, prefersBorder: false };

export function registerViewerResource(server) {
  registerAppResource(server, 'Odeuropa image viewer', VIEWER_RESOURCE_URI,
    { description: 'Artwork image with the EOKG bounding boxes.', mimeType: RESOURCE_MIME_TYPE, _meta: { ui: UI_META } },
    async () => ({ contents: [{ uri: VIEWER_RESOURCE_URI, mimeType: RESOURCE_MIME_TYPE, text: html, _meta: { ui: UI_META } }] }));
}
